D.Strings[205342]="做得好，$n！潘妮看到明天的早餐一定會很興奮的！"
D.Strings[205343]="你一定有雙快手!我不敢相信你這麼快就抓了這些螃蟹來!"
D.Strings[205344]="這些螃蟹看起來很讚!我會把牠們清洗乾淨，並把你的貢獻告訴國王。謝啦!"
D.Strings[205345]="你有找到製作甜點用的糖嗎？"
D.Strings[205346]="這挑戰對你來說太難了嗎?"
D.Strings[205347]="做得漂亮，$n!我看你這幾天完全就是個漁夫的樣子。或許應該帶你上船，看你能做些什麼!"
D.Strings[205348]="餌有用嗎?"
D.Strings[205349]="這些鱸魚看起來品質很好，$n。把牠們煎一煎看味道如何!"
D.Strings[205350]="看來你成功避開鯊魚了。陷阱裡有抓到龍蝦嗎?"
D.Strings[205351]="看來陷阱有用!謝啦，$n!"
D.Strings[205352]="你有找到我的墜盒嗎?"
D.Strings[205353]="你找到了!我不敢相信它這些年來一直在水裡!你不知道這對我有多麼的重要，$n。"
D.Strings[205354]="你找到瀑布了嗎?"
D.Strings[205355]="這些鱸魚看起來太棒了$n。你何不加入我們今晚的炸魚餐會?"
D.Strings[205356]="殺蜘蛛的工作做得很好，$n。照這個情況，我們馬上就能攻下這個森林了。"
D.Strings[205357]="願他們的靈魂安息。"
D.Strings[205358]="你做到了!也許我們現在終於可以讓船隻進港了。謝謝你 $n。"
D.Strings[205359]="那些鬼嚇到你了嗎？"
D.Strings[205360]="我沒想到你真的能辦到，$n。你的能力真是讓人讚嘆，不是嗎？"
D.Strings[205361]="幹得好，$n!我們很快就不會聽見那些鬼叫的聲音了。"
D.Strings[205362]="那個磁鐵裝置玩意真的有用嗎？"
D.Strings[205363]="這些零件真的幫了我們大忙，$n！誰想得到你能在那些古老垃圾裡頭找到這麼有用的東西？"
D.Strings[205364]="你殺死他了？我們試著殺掉那傢伙已經好幾週了！我們都很感謝你，$n。"
D.Strings[205365]="就跟你說那個村莊裡都是瘋子。把那裡清乾淨真是做得好，$n。"
D.Strings[205366]="抓到那些鮭魚了嗎？"
D.Strings[205367]="這些魚太漂亮了，$n!我覺得你現在已經駕輕就熟了。"
D.Strings[205368]="太漂亮了，$n!格瑞諾爾聽到這個消息的時候一定會感到很驕傲的!$B$B噢，他曾說過如果計畫成功的話，要把這個交給你。"
D.Strings[205369]="就像我常說的，吃飽的守衛就是開心的守衛。非常感謝你的幫助，$n。"
D.Strings[205370]="你拿到所有的材料了嗎？"
D.Strings[205371]="你全都拿到了？太好了！我馬上就開始準備。"
D.Strings[205372]="香料麵包的進展如何？"
D.Strings[205373]="那片麵包看起來真是美味可口。謝啦，$n。"
D.Strings[205374]="训练沙袋就在山坡下。练习完成后就来找我吧。"
D.Strings[205375]="干得不错，$n。你的确选择了正确的道路。$B$B很好。我们继续吧。"
D.Strings[205376]="某些時刻，你必須信任自己的直覺，並單純地做出反應。"
D.Strings[205377]="能如此轻易地从我手中夺过火焰，你可真是不简单。$B$B戒酒令是由我的先祖们代代相传下来的智慧卷轴。它源自一个更加和平的年代。$B$B每一件事物都有其适用的时代和背景，当黑暗即将降临时，它就不合时宜了。$B$B烧毁卷轴说明我们顺应局势并采取行动的决心，而你手中的火焰将照亮我们的未来。"
D.Strings[205378]="真是令人惊讶，$n。果然你是注定将要踏上$c之道的人。"
D.Strings[205379]="你是來找艾莎的嗎？你…最好不要在她完成修行前打擾到她。在完成整套訓練之前她是不會和任何人說話的。$B$B在等待的時候，你能幫幫我嗎？我在森林妖精的問題上遇到了一些麻煩。"
D.Strings[205380]="氣球都找回來了嗎，$g先生:小姐;？"
D.Strings[205381]="你不用担心会伤到这些树精。它们不过是成了精的植物，很快就会重新发芽。"
D.Strings[205382]="有时，我们需要沉思冥想；有时，我们则需要果断行动。两者间的平衡发展就是我们所追求的最高境界。"
D.Strings[205383]="很不错，我年轻的徒弟。$B$B这里的其他徒弟大多经过了长时间的训练，而你接受训练的时间还不到一小时，却能够击败他们。$B$B这值得赞扬，但我还有其他东西要教给你。"
D.Strings[205384]="拿起自己的第一件武器也是一种象征。每一个离开习武场的$c都必须做好拿起武器，保护他们的熊猫人同胞的准备。"
D.Strings[205385]="不错的武器。它应该可以发挥你的能力。$B$B现在，来用用看吧。"
D.Strings[205386]="完成湖中试炼。"
