D.Strings[205475]="瘤背熊怪的堕落威胁到了所有沉睡中的暗夜精灵德鲁伊。没有保护的话，他们脆弱的身体将不复存在。"
D.Strings[205476]="奥肯斯古尔的残存有如一声警钟，提醒我们泰达希尔的腐化扩散有多么严重，曾经和谐的自然生物如今却变成了梦魇般的怪物。"
D.Strings[205477]="即使是艾露恩最纯净的造物也会受到堕落和腐蚀的影响。将平静带给它们是我们的使命。"
